		sysconv(bit, o.status & 0x4) AS is_system,
		r.indepid AS function_id
	FROM sys.sysclsobjs o
	JOIN sys.syssingleobjrefs r ON r.depid = o.id AND r.class = 31 AND r.depsubid = 0 -- SRC_PRTSCHFUNC
