CREATE VIEW sys.partitions AS
	WITH partitions_columnstore(partition_id, object_id, index_id, partition_number, hobt_id, rows, filestream_filegroup_id, data_compression, data_compression_desc)
	AS
	(
		SELECT
			MAX(CASE WHEN ownertype = 1 THEN rs.rowsetid ELSE CAST(0 AS bigint) END)
				AS partition_id, -- ownertype 1 corresponds to ordinary rowsets.
			rs.idmajor AS object_id, -- The following 3 columns form a unique
			rs.idminor AS index_id,  -- Composite ID for a partition.
			rs.numpart AS partition_number, -- This is the third column
			MAX(CASE WHEN ownertype = 1 THEN rs.rowsetid ELSE CAST(0 AS bigint) END)
				AS hobt_id,
			SUM(CASE -- ownertype 2 corresponds to deleted bitmaps.
					WHEN ownertype = 2 THEN -isnull(ct.rows, rs.rcrows) -- Flip sign of deleted bitmaps
					ELSE isnull(ct.rows, rs.rcrows) -- delta stores are ownertype 3 and included here.
				END)
				AS rows,
			MAX(CASE WHEN ownertype = 1 THEN rs.fgidfs ELSE CAST(0 AS smallint) END)
				AS filestream_filegroup_id,
			MAX(CASE WHEN ownertype = 1 THEN cmprlevel ELSE CAST(0 AS tinyint) END)
				AS data_compression,
			MAX(CASE WHEN ownertype = 1 THEN cl.name ELSE CAST('' AS nvarchar(60)) END)
				AS data_compression_desc
		FROM sys.sysrowsets rs OUTER APPLY OpenRowset(TABLE ALUCOUNT, rs.rowsetid, 0, 0) ct
		LEFT JOIN sys.syspalvalues cl ON cl.class = 'CMPL' AND cl.value = cmprlevel
		WHERE (sysconv(bit, rs.status & 0x00010000) = 1 AND ownertype = 1) -- Consider only columnstore base indexes,
			OR ownertype IN (2,3) -- deleted bitmaps, and delta stores
		GROUP BY rs.idmajor, rs.idminor, rs.numpart
	),
	partitions_rowstore(partition_id, object_id, index_id, partition_number, hobt_id, rows, filestream_filegroup_id, data_compression, data_compression_desc)
	AS
	(
		SELECT
			rs.rowsetid AS partition_id,
			rs.idmajor AS object_id, -- The following 3 columns form a unique
			rs.idminor AS index_id,  -- Composite ID for a partition.
			rs.numpart AS partition_number, -- This is the third column
			rs.rowsetid AS hobt_id,
			isnull(ct.rows, rs.rcrows) AS rows,
			rs.fgidfs AS filestream_filegroup_id,
			cmprlevel AS data_compression,
			cl.name AS data_compression_desc
		FROM sys.sysrowsets rs OUTER APPLY OpenRowset(TABLE ALUCOUNT, rs.rowsetid, 0, 0) ct
		LEFT JOIN sys.syspalvalues cl ON cl.class = 'CMPL' AND cl.value = cmprlevel
		WHERE rs.ownertype = 1 and sysconv(bit, rs.status & 0x00010000) = 0 -- Ignore columnstore base indexes and orphaned rows.
	)
	SELECT * from partitions_rowstore
	WHERE 0 != index_id OR 0 = OBJECTPROPERTY(object_id, 'TableIsMemoryOptimized')
	UNION ALL
	SELECT * from partitions_columnstore
go

grant select on sys.partitions to [public]
go

CREATE VIEW sys.plan_guides AS
	SELECT 
		plan_guide_id 	= g.id,
		name 		= g.name, 
		create_date 	= g.created,
		modify_date 	= g.modified,
		is_disabled 	= sysconv(bit, g.status & 1),
		query_text 	= convert(nvarchar(max), p.stmt),
		scope_type 	= g.scopetype,
		scope_type_desc 	= convert(nvarchar(60), case g.scopetype 
								when  1 then 'OBJECT' 
								when  2 then 'SQL'
								else 'TEMPLATE' end),
		scope_object_id = sysconv(int, case g.scopetype when 1 then g.scopeid end), -- object-id is non-NULL only for module-scoped guide
		scope_batch 	= convert(nvarchar(max), p.batch), -- for single-stmt batch, batch_text is always NULL
		parameters 		= convert(nvarchar(max), p.params),
		hints 			= convert(nvarchar(max), p.hints)
	FROM sys.syssqlguides g CROSS APPLY OpenRowset(TABLE PLANGUIDES, g.id, g.scopeid, g.scopetype) p	
	WHERE g.scopeid <> 0 -- filter-out batch entries
go

grant select on sys.plan_guides to [public]
go

