		is_identity, is_computed, is_filestream,
		is_replicated, is_non_sql_subscribed,
		is_merge_published, is_dts_replicated,
		is_xml_document, xml_collection_id,
		default_object_id, rule_object_id,
		is_sparse, is_column_set
