		is_replicated, has_replication_filter, has_opaque_metadata,
		has_unchecked_assembly_data, with_check_option,
		is_auto_dropped as is_date_correlation_view,
		is_tracked_by_cdc
	FROM sys.objects$
	WHERE type = 'V'
		AND is_catalog_hidden = 0
