                    from
                    inserted ' + quotename(object_name(@objid)) + ', ' 
                    + @owner_qualified_immediate_child_table_name + ' ' + @immediate_child_table_name  + ' with (rowlock)
                    where ' + '(' + @join_filterclause + ')' + '
                    and not exists 
