                    '
            end

            insert into #tmptriggercmd (phase, cmdtext) values(14, @command3)

            select @command3 = '
            end    '
            insert into #tmptriggercmd (phase, cmdtext) values(14, @command3)

            --select @command3 = '
            --delete ' + @current_mappings_viewname + ' from 
