                        @lineage_new96,
                        @rowguid97,
                        @metadata_type97, 
                        @generation97,
                        @lineage_old97,
                        @lineage_new97,
                        @rowguid98,
                        @metadata_type98, 
                        @generation98,
                        @lineage_old98,
                        @lineage_new98,
                        @rowguid99,
                        @metadata_type99, 
                        @generation99,
                        @lineage_old99,
                        @lineage_new99,
                        @rowguid100,
                        @metadata_type100, 
                        @generation100,
                        @lineage_old100,
                        @lineage_new100
    
    if @@error<>0 and @retcode=1
        return 0

    return @retcode
go

