create procedure BP_PRD.sys.sp_catalogs_rowset_rmt
(
    @server_name    sysname,
    @catalog_name   sysname = NULL
)
as
    select
        CATALOG_NAME,
        DESCRIPTION
    from
        sys.fn_remote_catalogs (@server_name, @catalog_name)
    where
