        sys.spt_columns_view s_cv

    where
        (
            (@table_schema is null and s_cv.TABLE_NAME = @table_name) or
             s_cv.object_id = object_id(quotename(@table_schema) + '.' + quotename(@table_name))
        ) and
        (@column_name = s_cv.COLUMN_NAME or @column_name is null)

