create procedure BP_PRD.sys.sp_helparticle
(
    @publication sysname,         /* The publication name */
    @article sysname = '%',       /* The article name */
    @returnfilter bit = 1,        /* Return filter flag */
    @publisher sysname = NULL,
    @found	int  = 0 OUTPUT
)
AS
BEGIN
    DECLARE @cmd nvarchar(4000)
	DECLARE @retcode int
	DECLARE @publisher_type sysname

    select @retcode = 0

    EXEC @retcode = sys.sp_MSrepl_getpublisherinfo	@publisher			= @publisher,
													@publisher_type		= @publisher_type OUTPUT,
													@rpcheader			= @cmd OUTPUT,
													@skipSecurityCheck	= 1
													
    IF @retcode <> 0
        RETURN (@retcode)

	SET @publisher = UPPER(@publisher) COLLATE DATABASE_DEFAULT

	IF @publisher_type <> N'MSSQLSERVER'
	BEGIN
		select @cmd = @cmd + N'sys.sp_IHhelparticle'

		EXEC @retcode = @cmd
						@publication,
						@article,
						@returnfilter,
						@publisher,
						@publisher_type,
						@found OUTPUT
	END
	ELSE
	BEGIN
		select @cmd = @cmd + N'sys.sp_MSrepl_helparticle'

		EXEC @retcode = @cmd
				@publication,
				@article,
				@returnfilter,
				@publisher,
				@found OUTPUT
	END
	
    RETURN (@retcode)
END
go

