CREATE PROCEDURE sys.sp_sqlagent_add_job
    @job_name               SYSNAME, 
    @enabled                TINYINT = 1, -- 0 = Disabled, 1 = Enabled 
    @description            NVARCHAR(512) = NULL, 
    @start_step_id          INT = 1, 
    @notify_level_eventlog  INT = 2, -- 0 = Never, 1 = On Success, 2 = On Failure, 3 = Always 
    @delete_level           INT = 0, -- 0 = Never, 1 = On Success, 2 = On Failure, 3 = Always 
    @job_id                 UNIQUEIDENTIFIER = NULL OUTPUT 
AS 
BEGIN 
    DECLARE @retval INT 

    -- Validate if current db context is supported
    EXEC @retval = sys.sp_sqlagent_verify_database_context
    IF (@retval <> 0)
    BEGIN
        RETURN(@retval)
    END

    IF (@job_id IS NULL) 
    BEGIN 
        -- Assign new GUID for the job
        SELECT @job_id = NEWID() 
    END 

    INSERT INTO sys.sqlagent_jobs 
    (
        job_id, 
        name, 
        enabled, 
        description, 
        start_step_id, 
        notify_level_eventlog, 
        delete_level, 
        date_created, 
        date_modified
    ) 
    VALUES 
    (
        @job_id, 
        @job_name, 
        @enabled, 
        @description, 
        @start_step_id, 
        @notify_level_eventlog, 
        @delete_level, 
        GETDATE(), 
        GETDATE() 
    ) 

    SELECT @retval = @@error 

    -- If Insert job failed, then we dont need to notify sql agent
    IF (@retval <> 0)
    BEGIN
        RETURN(@retval)
    END

    --Notify SQL Agent that  new job was created
    EXECUTE @retval = master.dbo.xp_sqlagent_notify 
        N'J',
        @job_id,
        NULL,
        NULL,
        N'I',
        NULL,
        1,
        @@trancount,
        NULL
    
    RETURN(@retval) -- 0 means success 
    
END 
go

CREATE PROCEDURE sys.sp_sqlagent_add_jobstep
    @job_id                UNIQUEIDENTIFIER = NULL,   -- Must provide either this or job_name
    @job_name              SYSNAME          = NULL,   -- Must provide either this or job_id
    @step_id               INT              = NULL,   
    @step_name             SYSNAME,
    @subsystem             NVARCHAR(40)     = N'TSQL',
    @command               NVARCHAR(MAX)    = NULL,
    @additional_parameters NVARCHAR(MAX)    = NULL,
    @cmdexec_success_code  INT              = 0,
    @on_success_action     TINYINT          = 1,      -- 1 = Quit With Success, 2 = Quit With Failure, 3 = Goto Next Step, 4 = Goto Step
    @on_success_step_id    INT              = 0,
    @on_fail_action        TINYINT          = 2,      -- 1 = Quit With Success, 2 = Quit With Failure, 3 = Goto Next Step, 4 = Goto Step
    @on_fail_step_id       INT              = 0,
    @server                SYSNAME          = NULL,
    @database_name         SYSNAME          = NULL,
    @database_user_name    SYSNAME          = NULL,
    @retry_attempts        INT              = 0,      
    @retry_interval        INT              = 0,      
    @os_run_priority       INT              = 0,      
    @output_file_name      NVARCHAR(200)    = NULL,
    @flags                 INT              = 128,     -- 128  - System jobstep flag
    @step_uid UNIQUEIDENTIFIER              = NULL OUTPUT
AS
BEGIN
    DECLARE @job_id_as_char VARCHAR(36)
    DECLARE @retval INT

    -- Validate if current db context is supported
    EXEC @retval = sys.sp_sqlagent_verify_database_context
    IF (@retval <> 0)
    BEGIN
        RETURN(@retval)
    END
    
    -- job name / job id is accepted. not both
    IF ((@job_name IS NULL)     AND (@job_id IS NULL)) OR
    ((@job_name IS NOT NULL) AND (@job_id IS NOT NULL))
    BEGIN
        RAISERROR(14294, -1, -1, '@job_id', '@job_name')
        RETURN(1) -- Failure
    END
   
    -- if job_id null, then get the jobid for given job name
    IF (@job_id IS NULL)
    BEGIN
        SELECT @job_id = job_id
        FROM sys.sqlagent_jobs
        WHERE name = @job_name

        -- If returned job_id is null, then throw validation error
        IF(@job_id IS NULL)
        BEGIN
            RAISERROR(14262, -1, -1, '@job_name', @job_name)
            RETURN(1) -- Failure
        END
    END
    
    -- Validate if given job_id exists in agent_jobs
    IF NOT EXISTS (SELECT name
                FROM sys.sqlagent_jobs
                WHERE job_id = @job_id)
    BEGIN
      SET @job_id_as_char = CONVERT(VARCHAR(36), @job_id)
      RAISERROR(14262, -1, -1, '@job_id', @job_id_as_char)
      RETURN(1) -- Failure
    END

    SELECT @step_uid = NEWID()

     -- Default step id (if not supplied)
    IF (@step_id IS NULL)
    BEGIN
        SELECT @step_id = ISNULL(MAX(step_id), 0) + 1
        FROM sys.sqlagent_jobsteps
        WHERE job_id = @job_id
    END

    -- Insert the step
    INSERT INTO sys.sqlagent_jobsteps
    (
        job_id,
        step_id,
        step_name,
        subsystem,
        command,
        flags,
        additional_parameters,
        cmdexec_success_code,
        on_success_action,
        on_success_step_id,
        on_fail_action,
        on_fail_step_id,
        [server],
        database_name,
        database_user_name,
        retry_attempts,
        retry_interval,
        os_run_priority,
        output_file_name,
        last_run_outcome,
        last_run_duration,
        last_run_retries,
        last_run_date,
        last_run_time,
        step_uid
    )
    VALUES 
    (
        @job_id,
        @step_id,
        @step_name,
        @subsystem,
        @command,
        @flags,
        @additional_parameters,
        @cmdexec_success_code,
        @on_success_action,
        @on_success_step_id,
        @on_fail_action,
        @on_fail_step_id,
        @server,
        @database_name,
        @database_user_name,
        @retry_attempts,
        @retry_interval,
        @os_run_priority,
        @output_file_name,
        0,
        0,
        0,
        0,
        0,
        @step_uid
    )

    SELECT @retval = @@error 

    -- If Insert jobstep failed, then we dont need to notify sql agent
    IF (@retval <> 0)
    BEGIN
        RETURN(@retval)
    END

    -- Notify SQL Agent that job was updated
    EXECUTE @retval = master.dbo.xp_sqlagent_notify 
        N'J',
        @job_id,
        NULL,
        NULL,
        N'U',
        NULL,
        1,
        @@trancount,
        NULL

    RETURN(@retval) -- 0 means success 
END
go

CREATE PROCEDURE sys.sp_sqlagent_delete_job
    @job_id                UNIQUEIDENTIFIER
AS 
BEGIN 
    DECLARE @retval INT 

    -- Validate if current db context is supported
    EXEC @retval = sys.sp_sqlagent_verify_database_context
    IF (@retval <> 0)
    BEGIN
        RETURN(@retval)
    END

    -- If  job_id is null, then throw validation error
    IF(@job_id IS NULL)
    BEGIN
        RAISERROR(14262, -1, -1, '@job_id', 'NULL')
        RETURN(1) --Failure
    END

    DECLARE @TranCounter INT
    SET @TranCounter = @@TRANCOUNT
    IF (@TranCounter > 0)
    BEGIN
        SAVE TRANSACTION tran_sqlagent_delete_job
    END
    ELSE
    BEGIN
        BEGIN TRANSACTION
    END

    BEGIN TRY
        -- Delete job  & its references
        -- Delete job step logs
        DELETE sys.sqlagent_jobsteps_logs
        FROM sys.sqlagent_jobsteps_logs jl,  sys.sqlagent_jobsteps  js
        WHERE js.job_id = @job_id
        AND js.step_uid = jl.step_uid

        -- Delete job history logs
        DELETE  sys.sqlagent_job_history 
        WHERE job_id = @job_id

        -- Delete job steps related to this job
        DELETE sys.sqlagent_jobsteps 
        WHERE job_id = @job_id

        -- Delete job
        DELETE sys.sqlagent_jobs 
        WHERE job_id = @job_id

        IF (@TranCounter = 0)
        BEGIN
            COMMIT TRANSACTION
        END
        RETURN (0)

    END TRY
    BEGIN CATCH
        -- If there is no parent transaction  and current request has an active user transaction, 
        -- but an error has occurred then Rollback transaction
        IF (@TranCounter = 0 OR XACT_STATE() = -1)
        BEGIN
            ROLLBACK TRANSACTION
        END
        ELSE IF (XACT_STATE() = 1)  
        BEGIN
            -- current request has an active user transaction
            -- rollback transaction to save point
            ROLLBACK TRANSACTION tran_sqlagent_delete_job
        END

        DECLARE @ErrorMessage   NVARCHAR(4000);
        DECLARE @ErrorSeverity  INT;
        DECLARE @ErrorState     INT;
        DECLARE @ErrorNumber    INT;
        DECLARE @ErrorLine      INT;
        DECLARE @ErrorProcedure NVARCHAR(200);
        SELECT @ErrorLine = ERROR_LINE(),
               @ErrorSeverity = ERROR_SEVERITY(),
               @ErrorState = ERROR_STATE(),
               @ErrorNumber = ERROR_NUMBER(),
               @ErrorMessage = ERROR_MESSAGE(),
               @ErrorProcedure = ISNULL(ERROR_PROCEDURE(), '-');

        RAISERROR (14684, @ErrorSeverity, -1 , @ErrorNumber, @ErrorSeverity, @ErrorState, @ErrorProcedure, @ErrorLine, @ErrorMessage);

        RETURN(1) --Failure
    END CATCH
    
    -- Notify Sql Agent on job deletion
    EXECUTE @retval = master.dbo.xp_sqlagent_notify 
        N'J',
        @job_id,
        NULL,
        NULL,
        N'D',
        NULL,
        1,
        @@trancount,
        NULL

    RETURN(@retval) -- 0 means success 
END 
go

CREATE PROCEDURE sys.sp_sqlagent_help_jobstep 
  @job_id                UNIQUEIDENTIFIER
AS
BEGIN
    DECLARE @job_id_as_char VARCHAR(36)
    DECLARE @retval INT

    -- Validate if current db context is supported
    EXEC @retval = sys.sp_sqlagent_verify_database_context
    IF (@retval <> 0)
    BEGIN
        RETURN(@retval)
    END

    -- If  job_id is null, then throw validation error
    IF(@job_id IS NULL)
    BEGIN
        RAISERROR(14262, -1, -1, '@job_id', 'NULL')
        RETURN(1) --Failure
    END

	-- Validate if given job_id exists in agent_jobs
    IF NOT EXISTS (SELECT name
                FROM sys.sqlagent_jobs
                WHERE job_id = @job_id)
    BEGIN
        SET @job_id_as_char = CONVERT(VARCHAR(36), @job_id)
        RAISERROR(14262, -1, -1, '@job_id', @job_id_as_char)
        RETURN(1) -- Failure
    END

     -- Select the system job's steps
    SELECT step_id,
        step_name,
        subsystem,
        command,
        flags,
        cmdexec_success_code,
        on_success_action,
        on_success_step_id,
        on_fail_action,
        on_fail_step_id,
        [server],
        database_name,
        database_user_name,
        retry_attempts,
        retry_interval,
        os_run_priority,
        output_file_name,
        last_run_outcome,
        last_run_duration,
        last_run_retries,
        last_run_date,
        last_run_time,
        NULL
    FROM sys.sqlagent_jobsteps
    WHERE (job_id = @job_id)
    ORDER BY job_id, step_id

    RETURN(0) -- Success
END
