CREATE PROCEDURE sys.sp_sqlagent_log_job_history
    @job_id               UNIQUEIDENTIFIER,
    @step_id              INT,
    @sql_message_id       INT = 0,
    @sql_severity         INT = 0,
    @message              NVARCHAR(4000) = NULL,
    @run_status           INT, 
    @run_date             INT,
    @run_time             INT,
    @run_duration         INT,
    @operator_id_emailed  INT = 0,
    @operator_id_paged    INT = 0,
    @retries_attempted    INT
AS
BEGIN
    DECLARE @retval INT

    -- Validate if current db context is supported
    EXEC @retval = sys.sp_sqlagent_verify_database_context
    IF (@retval <> 0)
    BEGIN
        RETURN(@retval)
    END

    -- If  job_id is null, then throw validation error
    IF(@job_id IS NULL)
    BEGIN
        RAISERROR(14262, -1, -1, '@job_id', 'NULL')
        RETURN(1) --Failure
    END

    -- Validate if given job_id exists in agent_jobs
    IF NOT EXISTS (SELECT name
                FROM sys.sqlagent_jobs
                WHERE job_id = @job_id)
    BEGIN
        DECLARE @job_id_as_char VARCHAR(36)
        SET @job_id_as_char = CONVERT(VARCHAR(36), @job_id)
        RAISERROR(14262, -1, -1, '@job_id', @job_id_as_char)
        RETURN(1) -- Failure
    END

    INSERT INTO sys.sqlagent_job_history
    (
        job_id,
        step_id,
        sql_message_id,
        sql_severity,
        [message],
        run_status,
        run_date,
        run_time,
        run_duration,
        operator_id_emailed,
        operator_id_paged,
        retries_attempted
    )
    VALUES (
        @job_id,
        @step_id,
        @sql_message_id,
        @sql_severity,
        @message,
        @run_status,
        @run_date,
        @run_time,
        @run_duration,
        @operator_id_emailed,
        @operator_id_paged,
        @retries_attempted
    )
  
    SET @retval = @@ERROR

    RETURN(@retval) -- 0 means success 
END
