CREATE PROCEDURE sys.sp_sqlagent_start_job 
  @job_id      UNIQUEIDENTIFIER
AS
BEGIN
    DECLARE @retval INT 
    DECLARE @user_name   NVARCHAR(100)
    DECLARE @job_id_as_char VARCHAR(36)

