(
    @publisher      sysname,
    @publisher_db   sysname,
    @publication    sysname
)
as
begin
    set nocount on
    declare @retcode int
            ,@stop tinyint

    set @retcode = 0
    set @stop = 1

    -- Security check
    exec @retcode = sys.sp_MSreplcheck_subscribe
